/// <summary>
/// METDeliveryNoteDP
/// </summary>

[SRSReportParameterAttribute(classstr(METDeliveryNoteContract))]
public class METDeliveryNoteDP extends SRSReportDataProviderBase
{
    METDeliveryNoteContract         contract;
    METDeliveryNoteLineTmp          linesTmp;
    METDeliveryNoteHeaderTmp        headerTmp;
    RefRecId                        packingSlipRecId;

    /// <summary>
    /// processReport
    /// </summary> 
   
}

Method.Source:
    public void processReport()
    {
        contract                    = this.parmDataContract() as METDeliveryNoteContract;
        packingSlipRecId            = contract.parmPackingSlipRecId();

        CompanyInfo                 companyInfo = CompanyInfo::find();
        CustPackingSlipJour         custPackingSlipJour = CustPackingSlipJour::findRecId(packingSlipRecId);
        CustPackingSlipTrans        custPackingSlipTrans;
        SysDocuBrandDetails         sysDocuBrandDetails;
       
        headerTmp.clear();

        select firstonly sysDocuBrandDetails 
            where sysDocuBrandDetails.ReportName == reportStr(METDeliveryNote)
            && sysDocuBrandDetails.BrandId == curExt();
        headerTmp.CompanyPhone = sysDocuBrandDetails.Phone;
        headerTmp.CompanyEmail = sysDocuBrandDetails.Email;
        headerTmp.DeliveryDocumentNo    = custpackingslipJour.PackingSlipId;
        headerTmp.DeliveryInstructions  = METSalesTable::findByRefRecId(SalesTable::find(custpackingslipJour.SalesId).RecId).DeliveryInstructions;
        headerTmp.RouteStop             = SalesTable::find(custpackingslipJour.SalesId).METRouteStop;
        headerTmp.ShipDate              = custpackingslipJour.DeliveryDate;
        headerTmp.OrderNo               = custpackingslipJour.SalesId;
        headerTmp.CustomerNumber        = custpackingslipJour.InvoiceAccount;
        headerTmp.CustomerAddress       = DirUtility::replaceAddressTokenLanguage(CustTable::find(custpackingslipJour.InvoiceAccount).statementAddress(), CustTable::find(custpackingslipJour.InvoiceAccount).languageId());
        headerTmp.CompanyName           = companyInfo.name();
        headerTmp.CompanyABN            = 'ABN: ' + companyInfo.CoRegNum;
        headerTmp.CompanyAddress        = companyInfo.postalAddress().Address;
        headerTmp.CompanyLogo           = CustTable::metGetCustReportLogo(custpackingslipJour.InvoiceAccount).getData();
        headerTmp.insert();

        while select custPackingSlipTrans
            where   custPackingSlipTrans.SalesId   == custPackingSlipJour.SalesId
        && custPackingSlipTrans.PackingSlipId == custPackingSlipJour.PackingSlipId
        && custPackingSlipTrans.DeliveryDate == custPackingSlipJour.DeliveryDate
    {
        linesTmp.clear();
        linesTmp.ProductCode         = custPackingSlipTrans.ItemId;
        linesTmp.Description       = custPackingSlipTrans.Name;   
        linesTmp.DeliverQuantity        = custPackingSlipTrans.Qty;
        linesTmp.OrderNo     = custPackingSlipTrans.OrigSalesId;
        linesTmp.UOM    = custPackingSlipTrans.SalesUnit;
        linesTmp.insert();
    }
    }

/// <summary>
/// getLinesTmp
/// </summary>
/// <returns>METDeliveryNoteLineTmp</returns>
[SrsReportDataSet(tableStr(METDeliveryNoteLineTmp))]
public METDeliveryNoteLineTmp getLinesTmp()
{
    select linesTmp;
    return linesTmp;
}

/// <summary>
/// getHeaderTmp
/// </summary>
/// <returns>METDeliveryNoteHeaderTmp</returns>
[SrsReportDataSet(tableStr(METDeliveryNoteHeaderTmp))]
public METDeliveryNoteHeaderTmp getHeaderTmp()
{
    select headerTmp;
    return headerTmp;
}
